/**
 * Seeds the brands and the 14 products. `created_at` falls one minute per row
 * in the captured order (newest first), so «الأحدث» reproduces the live list.
 */
export function seedLiveCatalog(raw: DatabaseSync): void {
  const brand = raw.prepare('INSERT INTO brands (id, slug, name_ar, name_en) VALUES (?, ?, ?, ?)');
  for (const b of LIVE_BRANDS) brand.run(b.id, b.slug, b.name_ar, b.name_en);
  const ins = raw.prepare(
    `INSERT INTO products (id, slug, name, description, price_iqd, prime_price_iqd, pro_price_iqd, status,
                           category_id, sub_category_id, brand_id, spec_fields, selling_type, sale_types,
                           stock, display_order, created_at)
     VALUES (?, ?, ?, '', ?, ?, ?, 'active', ?, ?, ?, ?, 'direct_sale', ?, ?, 0, ?)`
  );
  LIVE_PRODUCTS.forEach((p, i) => {
    const printer = p.sub_category_id === 'cat_printers_fdm';
    const minute = String(59 - i).padStart(2, '0');
    ins.run(
      p.id, p.slug, p.name, p.price_iqd, p.prime, p.pro, p.category_id, p.sub_category_id, p.brand_id,
      JSON.stringify(p.spec_fields),
      JSON.stringify(printer ? ['direct_sale', 'pre_order'] : ['direct_sale']),
      p.stock,
      `2026-09-20T10:${minute}:00.000Z`
    );
  });
}
